"use client";

import Container from "../ui/Container";
import { createPlaceholder } from "../../lib/placeholders";

export default function Hero() {
  const heroImages = {
    desktop: createPlaceholder({ width: 1600, height: 1000, fill: "#D4D0C8" }),
    tablet: createPlaceholder({ width: 1200, height: 900, fill: "#E8E4DC" }),
    mobile: createPlaceholder({ width: 800, height: 1100, fill: "#F2F0EB" }),
  };

  return (
    <section id="hero" className="relative min-h-screen">
      <div className="absolute inset-0">
        <picture className="block h-full w-full">
          <source media="(min-width: 1024px)" srcSet={heroImages.desktop} />
          <source media="(min-width: 640px)" srcSet={heroImages.tablet} />
          <img
            src={heroImages.mobile}
            alt="Интерьерный контекст с архитектурной геометрией."
            className="h-full w-full object-cover"
            loading="eager"
            fetchPriority="high"
          />
        </picture>
        <div className="absolute inset-0 bg-graphite/35" aria-hidden="true" />
      </div>

      <Container className="relative z-10 flex min-h-screen items-end pb-20 pt-32 text-linen">
        <div className="space-y-6">
          <p className="text-[13px] font-medium uppercase tracking-[0.2em]">
            Astra
          </p>
          <h1 className="text-balance text-4xl font-normal leading-tight sm:text-5xl lg:text-6xl">
            Архитектурные объекты из дерева и камня для частных интерьеров.
          </h1>
        </div>
      </Container>
    </section>
  );
}
