"use client";

import { useCallback, useEffect, useState, type MouseEvent } from "react";
import Container from "../ui/Container";

const navLinks = [
  { href: "#projects", label: "Проекты" },
  { href: "#workshop", label: "Мастерская" },
  { href: "#contact", label: "Контакт" },
];

export default function Header() {
  const [isOpen, setIsOpen] = useState(false);

  useEffect(() => {
    document.body.style.overflow = isOpen ? "hidden" : "";
    return () => {
      document.body.style.overflow = "";
    };
  }, [isOpen]);

  const handleAnchorClick = useCallback(
    (event: MouseEvent<HTMLAnchorElement>) => {
      setIsOpen(false);
      const target = event.currentTarget.getAttribute("href");
      if (!target || !target.startsWith("#")) {
        return;
      }
      const element = document.querySelector(target);
      if (element instanceof HTMLElement) {
        window.setTimeout(() => {
          element.focus({ preventScroll: true });
        }, 0);
      }
    },
    []
  );

  return (
    <header className="sticky top-0 z-50 border-b border-steel bg-warm">
      <Container className="flex min-h-[72px] items-center justify-between gap-4">
        <a
          href="#hero"
          className="focus-ring font-display text-lg font-normal tracking-tight"
        >
          Astra
        </a>

        <nav
          className="hidden items-center gap-6 text-[13px] font-medium uppercase tracking-[0.2em] text-graphite md:flex"
          aria-label="Основная навигация"
        >
          {navLinks.map((link, index) => (
            <a
              key={link.href}
              className="focus-ring min-h-[48px] px-2 py-3 transition duration-300 ease-out hover:opacity-70"
              href={link.href}
              onClick={handleAnchorClick}
            >
              {link.label}
              {index < navLinks.length - 1 ? "" : ""}
            </a>
          ))}
        </nav>

        <button
          type="button"
          className="focus-ring inline-flex h-12 w-12 items-center justify-center rounded-none border border-steel text-graphite md:hidden"
          aria-label={isOpen ? "Закрыть меню" : "Открыть меню"}
          aria-expanded={isOpen}
          aria-controls="mobile-navigation"
          onClick={() => setIsOpen((prev) => !prev)}
        >
          <span className="sr-only">
            {isOpen ? "Закрыть меню" : "Открыть меню"}
          </span>
          <span className="flex flex-col items-center gap-1">
            <span className="block h-0.5 w-5 bg-graphite" />
            <span className="block h-0.5 w-5 bg-graphite" />
            <span className="block h-0.5 w-5 bg-graphite" />
          </span>
        </button>
      </Container>

      <div
        className={`fixed inset-0 z-40 bg-warm transition-opacity duration-300 ease-out md:hidden ${
          isOpen ? "opacity-100" : "pointer-events-none opacity-0"
        }`}
      >
        <nav
          id="mobile-navigation"
          className="flex h-full flex-col justify-center gap-6 px-6 text-[13px] font-medium uppercase tracking-[0.2em] text-graphite"
          aria-label="Мобильная навигация"
        >
          {navLinks.map((link, index) => (
            <a
              key={link.href}
              className="focus-ring min-h-[48px] px-2 py-3 transition duration-300 ease-out hover:opacity-70"
              href={link.href}
              onClick={handleAnchorClick}
            >
              {link.label}
              {index < navLinks.length - 1 ? "" : ""}
            </a>
          ))}
        </nav>
      </div>
    </header>
  );
}
