"use client";

import Container from "../ui/Container";
import Section from "../ui/Section";

type PortfolioImage = {
  desktop: string;
  tablet: string;
  mobile: string;
  alt: string;
};

type PortfolioItem = {
  title: string;
  summary: string;
  details: Array<{ label: string; value: string }>;
  image: PortfolioImage;
};

type PortfolioProps = {
  items: PortfolioItem[];
};

export default function Portfolio({ items }: PortfolioProps) {
  return (
    <Section id="projects">
      <Container>
        <div className="grid gap-8 lg:grid-cols-12">
          <div className="lg:col-span-4">
            <h2 className="text-3xl font-normal sm:text-4xl">
              Последние проекты
            </h2>
          </div>
          <div className="lg:col-span-6 lg:col-start-6">
            <p className="text-measure text-base text-graphite">
              Каждый объект проектируется из контекста помещения, горизонта
              света и масштаба. Материал подчиняется пропорции, соединение
              подчёркивает конструкцию.
            </p>
          </div>
        </div>

        <div className="mt-12 grid gap-16">
          {items.map((item, index) => {
            const isReversed = index % 2 !== 0;
            return (
              <article
                key={item.title}
                className="grid items-start gap-8 md:grid-cols-12"
              >
                <div
                  className={`md:col-span-8 ${
                    isReversed ? "md:order-2" : "md:order-1"
                  }`}
                >
                  <div className="aspect-[4/3] w-full overflow-hidden border border-steel">
                    <picture className="block h-full w-full">
                      <source
                        media="(min-width: 1024px)"
                        srcSet={item.image.desktop}
                      />
                      <source
                        media="(min-width: 640px)"
                        srcSet={item.image.tablet}
                      />
                      <img
                        src={item.image.mobile}
                        alt={item.image.alt}
                        className="h-full w-full object-cover"
                        loading={index === 0 ? "eager" : "lazy"}
                        decoding="async"
                      />
                    </picture>
                  </div>
                </div>
                <div
                  className={`space-y-6 md:col-span-4 ${
                    isReversed ? "md:order-1" : "md:order-2"
                  }`}
                >
                  <div className="space-y-3">
                    <h3 className="text-2xl font-normal">{item.title}</h3>
                    <p className="text-base text-graphite">{item.summary}</p>
                  </div>
                  <dl className="space-y-3 border-t border-steel pt-4 text-sm text-graphite">
                    {item.details.map((detail) => (
                      <div
                        key={detail.label}
                        className="flex items-baseline justify-between gap-6"
                      >
                        <dt>{detail.label}</dt>
                        <dd className="text-right">{detail.value}</dd>
                      </div>
                    ))}
                  </dl>
                </div>
              </article>
            );
          })}
        </div>
      </Container>
    </Section>
  );
}
