"use client";

import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { leadSchema, type LeadFormValues } from "../../lib/validators";
import { track } from "../../lib/track";

type FormStatus = "idle" | "loading" | "success" | "error";

export default function LeadForm() {
  const [status, setStatus] = useState<FormStatus>("idle");
  const {
    register,
    handleSubmit,
    reset,
    formState: { errors },
  } = useForm<LeadFormValues>({
    resolver: zodResolver(leadSchema),
    defaultValues: {
      name: "",
      contact: "",
      comment: "",
      honeypot: "",
    },
  });

  const onSubmit = async (values: LeadFormValues) => {
    setStatus("loading");
    track("lead_submit");

    try {
      const response = await fetch("/api/lead", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(values),
      });

      if (!response.ok) {
        throw new Error("Request failed");
      }

      setStatus("success");
      track("lead_success");
      reset();
    } catch (error) {
      console.error(error);
      setStatus("error");
      track("lead_error");
    }
  };

  return (
    <section id="lead" className="py-16 sm:py-20 lg:py-24">
      <div className="mx-auto mt-8 w-full max-w-6xl px-4 sm:px-6 lg:px-8">
        <div className="mx-auto flex w-full max-w-3xl flex-col items-center text-center">
          <div className="space-y-2">
            <div className="mx-auto h-0.5 w-8 bg-walnut/70" aria-hidden="true" />
            <h2 className="font-display text-3xl font-semibold leading-tight sm:text-4xl">
              Обсудим ваш проект
            </h2>
          </div>
          <p className="mt-4 text-base text-graphite/70">
            Ответим с вариантами материалов и стоимостью. Обычно — в течение рабочего
            дня.
          </p>
        </div>

        <div className="mx-auto mt-10 w-full max-w-3xl space-y-3">
          <p className="text-center text-xs text-graphite/60">
            Договор. Гарантия. Собственное производство.
          </p>
          <form
            onSubmit={handleSubmit(onSubmit)}
            className="border border-steel/70 bg-linen/80 p-6"
            aria-live="polite"
          >
            <div className="space-y-6">
              <div>
                <label className="text-sm text-graphite/70" htmlFor="name">
                  Имя
                </label>
                <input
                  id="name"
                  type="text"
                  placeholder="Ваше имя"
                  className="focus-ring mt-2 w-full rounded-none border border-steel/70 bg-stone/80 px-4 py-2.5 text-base text-graphite placeholder:text-ash focus-visible:border-walnut"
                  {...register("name")}
                  aria-invalid={Boolean(errors.name)}
                  aria-describedby={errors.name ? "name-error" : undefined}
                />
                {errors.name && (
                  <p id="name-error" className="mt-2 text-sm text-rose-600">
                    {errors.name.message}
                  </p>
                )}
              </div>

              <div>
                <label className="text-sm text-graphite/70" htmlFor="contact">
                  Телефон
                </label>
                <input
                  id="contact"
                  type="text"
                  placeholder="+7 999 000-00-00"
                  className="focus-ring mt-2 w-full rounded-none border border-steel/70 bg-stone/80 px-4 py-2.5 text-base text-graphite placeholder:text-ash focus-visible:border-walnut"
                  {...register("contact")}
                  aria-invalid={Boolean(errors.contact)}
                  aria-describedby={errors.contact ? "contact-error" : undefined}
                />
                {errors.contact && (
                  <p id="contact-error" className="mt-2 text-sm text-rose-600">
                    {errors.contact.message}
                  </p>
                )}
              </div>

              <div>
                <label className="text-sm text-graphite/70" htmlFor="comment">
                  Сообщение
                </label>
                <textarea
                  id="comment"
                  rows={4}
                  placeholder="Кратко опишите задачу или пожелания"
                  className="focus-ring mt-2 w-full resize-none rounded-none border border-steel/70 bg-stone/80 px-4 py-2.5 text-base text-graphite placeholder:text-ash focus-visible:border-walnut"
                  {...register("comment")}
                  aria-invalid={Boolean(errors.comment)}
                  aria-describedby={errors.comment ? "comment-error" : undefined}
                />
                {errors.comment && (
                  <p id="comment-error" className="mt-2 text-sm text-rose-600">
                    {errors.comment.message}
                  </p>
                )}
              </div>

            <input
              type="text"
              tabIndex={-1}
              autoComplete="off"
              className="hidden"
              aria-hidden="true"
              {...register("honeypot")}
            />

            <button
              type="submit"
              className="focus-ring w-full rounded-none bg-graphite px-6 py-3 text-sm font-semibold uppercase tracking-[0.12em] text-linen transition hover:bg-charcoal disabled:cursor-not-allowed disabled:opacity-60"
              disabled={status === "loading"}
            >
              ОТПРАВИТЬ
            </button>

            {status === "success" && (
              <p className="text-center text-sm text-graphite">
                Спасибо. Мы свяжемся с вами в течение дня.
              </p>
            )}

            {status === "error" && (
              <div className="rounded-2xl border border-rose-200 bg-rose-50 px-4 py-3 text-sm text-rose-700">
                Не удалось отправить. Попробуйте ещё раз или напишите в мессенджер.
              </div>
            )}
            </div>
          </form>
        </div>
      </div>
    </section>
  );
}
